mapper.select:

	/*getIRSNo*/
       SELECT REPLACE (CMPY.IRS_NO, '-', '') AS IRS_NO
		  FROM ICOMLUSR USR, ICOMCMPY CMPY
		 WHERE     USR.COM_CODE = CMPY.COM_CODE
		       AND CMPY.STATUS != 'D'
		       AND USR.USER_ID = #{st_user_id}


	/*getPWD*/
       SELECT  PASSWORD AS PWD
		  FROM ICOMLUSR
		 WHERE USER_ID = #{userId}


	/*getLusrYn*/
       SELECT DECODE( COUNT(USER_ID),0,'N','Y') LUSR_YN
		  FROM ICOMLUSR
		 WHERE USER_ID = #{USER_ID}
		 AND COM_CODE = #{COM_CODE}


	/*getComCode*/
       SELECT MAX(COMPANY_CODE) AS COMPANY_CODE 
		FROM ICOMCOD2 
		 WHERE  TYPE = 'C005' 
		 AND CODE = #{appUserName}


	/*getRollYn*/
       SELECT DECODE( COUNT(CODE),0,'N','Y') LUSR_YN
		  FROM ICOMCOD1
		 WHERE TYPE= 'M145' 
		 AND CODE = #{appUserName}
		 AND FLAG  = 'Y'

