/*setPunchoutUserUpdate*/
UPDATE ICOMLUSR
   SET PASSWORD = #{password},
       PASS_CHANGE_DATE = TO_CHAR (SYSDATE, 'YYYYMMDD'),
       PASSWORD_TYPE = 'C',
       EMAIL  = #{userEmail}
       ,RETURN_URL = #{returnURL}
 WHERE USER_ID = #{appUserName}


/*setPunchoutRollDel*/
DELETE KX_USERAUTH
WHERE USER_ID = #{appUserName}

