/*setIkenSsoNm*/
SELECT USER_NAME_LOC
  FROM (
	SELECT NVL (TRIM (A.USER_NAME_LOC), '') AS USER_NAME_LOC
	  FROM ICOMLUSR A
	 WHERE A.COM_CODE       = #{COM_CODE}
	   AND A.LEGACY_USER_ID = #{EMP_NO}
	   AND A.STATUS IN ('C','R')
	   AND (A.OFFICE_YN IS NULL OR A.OFFICE_YN <> 'Y' )
  )
 WHERE ROWNUM = 1


/*setIkenSsoPw*/
SELECT A.PASSWORD  AS PWD
  FROM ICOMLUSR A
 WHERE USER_ID = #{KITA_ID}
 AND (OFFICE_YN IS NULL OR OFFICE_YN <> 'Y' )

