/*setSamkeeSsoId*/
SELECT NVL(MAX(USR.USER_ID), '') AS USER_ID
 ,TO_CHAR(COUNT(USR.USER_ID)) AS USER_COUNT
FROM ICOMLUSR USR 
WHERE USR.COM_CODE IN (
	SELECT COD.CODE2 FROM ICOMCOD3 COD
	WHERE COD.TYPE ='SSO'
	AND COD.CODE1 = #{TYPE} 
	AND COD.FLAG = 'Y'
)
AND STATUS != 'D'
AND USR.EMAIL = #{EMP_NO}


	/*setCodIkenSsoId*/
	SELECT USER_ID
    FROM ICOMLUSR USR 
    WHERE USR.COM_CODE IN (
		SELECT COD.CODE2 FROM ICOMCOD3 COD
		WHERE COD.TYPE ='SSO'
		AND COD.CODE1  = #{COM_CODE}
		AND COD.FLAG = 'Y'
		)
    AND STATUS != 'D'
    AND USR.LEGACY_USER_ID = #{EMP_NO}
    AND ROWNUM = 1


/*setCodIkenSyfSsoId*/
SELECT 
	USER_ID
FROM (
	SELECT USER_ID
    FROM ICOMLUSR USR 
    WHERE USR.COM_CODE IN (
		SELECT COD.CODE2 FROM ICOMCOD3 COD
		WHERE COD.TYPE ='SSO'
		AND COD.CODE1  = #{COM_CODE}
		AND COD.FLAG = 'Y'
		)
    AND STATUS IN ('C', 'R')
    AND USR.EMAIL = #{EMP_NO}
)    
WHERE ROWNUM = 1

